// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { RdfExplorer, clearMetadataCache } from "../../../main/frontend/graph-explorer/rdf-explorer.ts";
import { RepositoryFacetStore } from "../../../main/frontend/graph-explorer/repository-facets.ts";
import { RDFS_LABEL } from "../../../main/frontend/graph-explorer/rdf-vocabulary.ts";
import { QueryFailure } from "../../../main/frontend/graph-explorer/request-batching.ts";

const iri = (value) => ({ type: "uri", value });
const literal = (value, extra = {}) => ({ type: "literal", value, ...extra });
const requestedNodes = (query) => [...new Set([...query.matchAll(/<(urn:n:\d+)>/g)].map((match) => match[1]))];

/** Like the Graph servlet: at most `maxRows` rows, and `rdf4j:truncated` says whether more were cut off. */
function cutAt(maxRows, rowsOf) {
  return async (query) => {
    const bindings = rowsOf(query);
    return { results: { bindings: bindings.slice(0, maxRows) }, "rdf4j:truncated": bindings.length > maxRows };
  };
}

test("a batch of node lookups the servlet cut off is asked for again in smaller batches", async () => {
  const ids = Array.from({ length: 16 }, (_, index) => `urn:n:${index}`);
  const explorer = new RdfExplorer("urn:endpoint:cut-predicates", ["en"], cutAt(5000, (query) =>
    requestedNodes(query).flatMap((id) => Array.from({ length: 400 }, (_, index) => ({
      selected: iri(id),
      predicate: iri(`urn:p:${index}`),
      direction: literal("outgoing"),
    })))));
  try {
    const rows = await explorer.predicates(ids);
    const perNode = new Map(ids.map((id) => [id, 0]));
    for (const row of rows) perNode.set(row.selected.value, perNode.get(row.selected.value) + 1);
    assert.deepEqual([...perNode.values()], ids.map(() => 400), "every node has all of its predicates");
  } finally {
    explorer.dispose();
    clearMetadataCache();
  }
});

test("a label batch the servlet cut off below 4,096 rows is asked for again in smaller batches", async () => {
  const ids = Array.from({ length: 32 }, (_, index) => `urn:n:${index}`);
  const explorer = new RdfExplorer("urn:endpoint:cut-labels", ["en"], cutAt(1000, (query) =>
    requestedNodes(query).flatMap((id) => Array.from({ length: 40 }, (_, index) => ({
      resource: iri(id),
      label: literal(`Name ${id.split(":").at(-1)} ${index}`, { "xml:lang": "en" }),
      labelProperty: iri(RDFS_LABEL),
    })))));
  try {
    await explorer.resolve(ids);
    const unlabelled = ids.filter((id) => !explorer.label(id).startsWith("Name "));
    assert.deepEqual(unlabelled, [], "no resource is left checked without its labels");
  } finally {
    explorer.dispose();
    clearMetadataCache();
  }
});

test("values of a capped hub that the servlet cut off are not taken as complete", async () => {
  const hub = "http://example.org/hub";
  const statements = [];
  // Interleaved, so a census that stops at its cap sees only part of each predicate's values.
  for (let index = 0; index < 50; index++) {
    statements.push(["http://example.org/a", literal(`a${index}`)], ["http://example.org/b", literal(`b${index}`)]);
  }
  const execute = cutAt(30, (query) => {
    const limits = [...query.matchAll(/LIMIT (\d+)/g)].map((match) => Number(match[1]));
    if (/^SELECT \?s \?p \?o/.test(query)) {
      return statements.slice(0, limits[0]).map(([p, o]) => ({ s: iri(hub), p: iri(p), o }));
    }
    if (/^SELECT \?p \(COUNT/.test(query)) {
      const counts = new Map();
      statements.slice(0, limits[0]).forEach(([p]) => counts.set(p, (counts.get(p) ?? 0) + 1));
      return [...counts].map(([p, n]) => ({ p: iri(p), n: literal(String(n)) }));
    }
    if (/^SELECT \?p \?o/.test(query)) {
      const predicates = [...query.matchAll(/SELECT DISTINCT \(<([^>]+)> AS \?p\)/g)].map((match) => match[1]);
      return predicates.flatMap((p, index) => statements.filter(([predicate]) => predicate === p)
        .slice(0, limits[index]).map(([, o]) => ({ p: iri(p), o })));
    }
    return [];
  });
  const store = new RepositoryFacetStore({ execute, scope: "default", maxRows: 30, censusCap: 20, perNodeCap: 1 });
  store.want([hub], "background");
  for (let turn = 0; turn < 2000 && store.status().loading; turn++) await new Promise((resolve) => setTimeout(resolve, 1));
  const cell = store.get(hub)?.predicates.get("http://example.org/a");
  assert.ok(cell, "the hub was loaded");
  assert.ok(cell.values.length < 50);
  assert.equal(cell.complete, false, "a cell the servlet cut short is not complete");
  store.dispose();
});

test("expanding a large selection with loaded links stays within the servlet's query length and row cap", async () => {
  // 250 nodes: one query would be about 200,000 characters and up to 6,000 rows.
  const ids = Array.from({ length: 250 }, (_, index) => `http://example.org/a-rather-long-namespace/resource-${index}`);
  const loaded = new Map(ids.map((id) => [id, {
    outgoing: Array.from({ length: 5 }, (_, index) => ["<http://example.org/vocabulary/linksTo>", `<${id}/loaded-${index}>`]),
    incoming: Array.from({ length: 5 }, (_, index) => [`<${id}/loaded-from-${index}>`, "<http://example.org/vocabulary/linksTo>"]),
  }]));
  const cut = cutAt(5000, (query) =>
    [...new Set([...query.matchAll(/<(http:\/\/example\.org\/a-rather-long-namespace\/resource-\d+)>/g)].map((match) => match[1]))]
      .flatMap((id) => ["source", "target"].flatMap((role) => Array.from({ length: 12 }, (_, index) => ({
        selected: iri(id),
        source: iri(role === "source" ? id : `${id}/from-${index}`),
        predicate: iri("http://example.org/vocabulary/linksTo"),
        target: iri(role === "source" ? `${id}/to-${index}` : id),
      })))));
  const explorer = new RdfExplorer("urn:endpoint:cut-expand", ["en"], async (query, signal) => {
    if (query.length > 150000) throw new QueryFailure("The query is too long for the Workbench.", 413);
    return cut(query, signal);
  }, "default", false, true);
  try {
    const rows = await explorer.expand(ids, 12, undefined, loaded);
    const perNode = new Map(ids.map((id) => [id, 0]));
    for (const row of rows) perNode.set(row.selected.value, perNode.get(row.selected.value) + 1);
    assert.deepEqual([...perNode.values()], ids.map(() => 24), "every selected node gets its links");
  } finally {
    explorer.dispose();
    clearMetadataCache();
  }
});
